declare const tools: { mcp__engram__mem_save(args: {
  // Automatically capture the current user prompt when available (default: true). Set false for SDD artifacts or automated saves.
  capture_prompt?: boolean;
  // Structured content using **What**, **Why**, **Where**, **Learned** format. Required unless observation alias is provided.
  content?: string;
  // Backward-compatible alias for content. Prefer content for new clients.
  observation?: string;
  // Optional explicit project for this memory. Accepted only when backed by known context (existing project, matching session, repo config, or ambiguous-project recovery); invalid or unbacked names fail loudly.
  project?: string;
